PRAGMA foreign_keys = ON;
CREATE TABLE users(tgid TEXT PRIMARY KEY,first_name TEXT NOT NULL DEFAULT '',last_name TEXT NOT NULL DEFAULT '',username TEXT,first_contact INTEGER NOT NULL,blocked INTEGER NOT NULL DEFAULT 0 CHECK(blocked IN(0,1)),thread_id INTEGER UNIQUE,binding_version INTEGER NOT NULL DEFAULT 0,card_id INTEGER,photo_id TEXT);
CREATE TABLE thread_history(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,thread_id INTEGER NOT NULL,version INTEGER NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE inbox_updates(update_id INTEGER PRIMARY KEY,payload TEXT NOT NULL,received_at INTEGER NOT NULL);
CREATE TABLE jobs(id INTEGER PRIMARY KEY AUTOINCREMENT,dedupe TEXT UNIQUE NOT NULL,user_key TEXT NOT NULL,kind TEXT NOT NULL,payload TEXT NOT NULL,state TEXT NOT NULL,due_at INTEGER NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,epoch TEXT NOT NULL,created_at INTEGER NOT NULL,error TEXT);
CREATE INDEX jobs_recovery ON jobs(state,due_at);
CREATE INDEX jobs_user ON jobs(user_key,id);
CREATE TABLE messages(id INTEGER PRIMARY KEY AUTOINCREMENT,user_id TEXT NOT NULL,direction TEXT NOT NULL,source_chat TEXT NOT NULL,source_id INTEGER NOT NULL,admin_id INTEGER,private_id INTEGER,thread_id INTEGER,business INTEGER NOT NULL DEFAULT 1,media_group TEXT,received_at INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 0,delivery TEXT NOT NULL DEFAULT 'pending',deletion TEXT NOT NULL DEFAULT 'none',tombstone INTEGER NOT NULL DEFAULT 0,payload TEXT NOT NULL,epoch TEXT NOT NULL DEFAULT 'initial',UNIQUE(source_chat,source_id));
CREATE INDEX messages_user ON messages(user_id,id);
CREATE INDEX messages_time ON messages(received_at,business,direction);
CREATE INDEX messages_admin ON messages(admin_id);
CREATE INDEX messages_recovery ON messages(epoch,direction,delivery,business,tombstone,id);
CREATE TABLE operations(op_key TEXT PRIMARY KEY,method TEXT NOT NULL,phase TEXT NOT NULL,result TEXT,reason TEXT,code INTEGER,due_at INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE delivery_events(id INTEGER PRIMARY KEY AUTOINCREMENT,op_key TEXT NOT NULL,method TEXT NOT NULL,status TEXT NOT NULL,code INTEGER,created_at INTEGER NOT NULL);
CREATE TABLE callback_actions(token TEXT PRIMARY KEY,kind TEXT NOT NULL,user_id TEXT NOT NULL,actor_id TEXT NOT NULL,thread_id INTEGER,version INTEGER NOT NULL,payload TEXT NOT NULL,expires_at INTEGER NOT NULL,used INTEGER NOT NULL DEFAULT 0);
CREATE TABLE deletion_batches(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,boundary INTEGER NOT NULL,state TEXT NOT NULL DEFAULT 'pending',created_at INTEGER NOT NULL);
CREATE TABLE deletion_items(batch_id TEXT NOT NULL,message_id INTEGER NOT NULL,result TEXT NOT NULL DEFAULT 'pending',PRIMARY KEY(batch_id,message_id));
CREATE TABLE media_groups(group_key TEXT PRIMARY KEY,user_id TEXT NOT NULL,direction TEXT NOT NULL,due_at INTEGER NOT NULL,version INTEGER NOT NULL DEFAULT 0);
CREATE TABLE audit_logs(id INTEGER PRIMARY KEY AUTOINCREMENT,event TEXT NOT NULL,detail TEXT NOT NULL,created_at INTEGER NOT NULL,reported INTEGER NOT NULL DEFAULT 0);
CREATE INDEX audit_pending ON audit_logs(reported,id);
CREATE TABLE media_batches(batch_key TEXT PRIMARY KEY,group_key TEXT NOT NULL,members TEXT NOT NULL,thread_id INTEGER,state TEXT NOT NULL DEFAULT 'pending');
CREATE INDEX media_batches_group ON media_batches(group_key,state);
